<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/db.php'; require_once __DIR__ . '/../includes/layout.php'; requireLogin();
$user = currentUser();
$stmt = $pdo->prepare("SELECT room_id FROM leases WHERE tenant_id = :tenant_id AND status = 'active' LIMIT 1"); $stmt->execute([':tenant_id' => $user['id']]); $lease = $stmt->fetch();
if (!$lease) redirectWith('dashboard.php', 'error', 'An active lease is required.');
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verifyCsrf($_POST['csrf_token'] ?? null); $category = trim((string) ($_POST['category'] ?? '')); $description = trim((string) ($_POST['description'] ?? '')); $priority = $_POST['priority'] ?? 'medium'; if ($category === '' || $description === '' || !in_array($priority, ['low','medium','high'], true)) redirectWith('request.php', 'error', 'Enter valid request details.'); $stmt = $pdo->prepare('INSERT INTO maintenance_tickets (tenant_id, room_id, category, description, priority) VALUES (:tenant_id, :room_id, :category, :description, :priority)'); $stmt->execute([':tenant_id'=>$user['id'], ':room_id'=>$lease['room_id'], ':category'=>$category, ':description'=>$description, ':priority'=>$priority]); redirectWith('dashboard.php', 'success', 'Maintenance request submitted.'); }
pageHeader('Maintenance Request'); ?>
<div class="max-w-2xl rounded-lg border border-slate-200 bg-white p-6 shadow-sm"><h1 class="text-2xl font-bold">Submit maintenance request</h1><form class="mt-6 space-y-4" method="post"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><label class="block text-sm font-semibold">Category<input class="mt-1 w-full rounded border border-slate-300 p-2" name="category" required></label><label class="block text-sm font-semibold">Priority<select class="mt-1 w-full rounded border border-slate-300 p-2" name="priority"><option>low</option><option selected>medium</option><option>high</option></select></label><label class="block text-sm font-semibold">Description<textarea class="mt-1 w-full rounded border border-slate-300 p-2" name="description" rows="5" required></textarea></label><button class="rounded bg-teal-700 px-4 py-2 font-semibold text-white" type="submit">Submit request</button></form></div><?php pageFooter(); ?>